="T16"><ts n="e" id="Seg_1530" s="T11" e="T12">(Vous) avez </ts><ts n="e" id="Seg_1532" s="T12" e="T13">donné votre petite </ts><ts n="e" id="Seg_1534" s="T13" e="T14">• • </ts><ts n="e" id="Seg_1536" s="T14" e="T15">pichenette. </ts><ts n="e" id="Seg_1538" s="T15" e="T16">((aspires)) </ts></ts><ts n="sc" id="Seg_1539" s="T17" e="T37"><ts n="e" id="Seg_1541" s="T17" e="T18">Je ne suis pas sortie de mes </ts><ts n="e" id="Seg_1543" s="T18" e="T19">gonds. </ts><ts n="e" id="Seg_1545" s="T19" e="T20">• • </ts><ts n="e" id="Seg_1547" s="T20" e="T21">Vous permettez. </ts><ts n="e" id="Seg_1549" s="T21" e="T22">Parce que moi aussi, j'ai l'intention de me faire respecter. </ts><ts n="e" id="Seg_1551" s="T22" e="T23">• • </ts><ts n="e" id="Seg_1553" s="T23" e="T24">Je ne suis pas sortie de mes gonds. </ts><ts n="e" id="Seg_1555" s="T24" e="T25">Je crois que ce qui nous différencie </ts><ts n="e" id="Seg_1557" s="T25" e="T26">• • </ts><ts n="e" id="Seg_1559" s="T26" e="T27">c'est une vision de la morale politique. </ts><ts n="e" id="Seg_1561" s="T27" e="T28">• • • </ts><ts n="e" id="Seg_1563" s="T28" e="T29">Et je pense </ts><ts n="e" id="Seg_1565" s="T29" e="T30">• • • </ts><ts n="e" id="Seg_1567" s="T30" e="T31">qu'il faut que les discours </ts><ts n="e" id="Seg_1569" s="T31" e="T32">soient cohérents avec les actes. </ts><ts n="e" id="Seg_1571" s="T32" e="T33">• • • </ts><ts n="e" id="Seg_1573" s="T33" e="T34">Et que quand il y un tel écart </ts><ts n="e" id="Seg_1575" s="T34" e="T35">on ne peut pas avoir détruit l'acceuil </ts><ts n="e" id="Seg_1577" s="T35" e="T36">des enfants handica</ts><ts n="e" id="Seg_1579" s="T36" e="T37">pés à l'école. </ts></ts><ts n="sc" id="Seg_1580" s="T38" e="T41"><ts n="e" id="Seg_1582" s="T38" e="T39">Non, ç</ts><ts n="e" id="Seg_1584" s="T39" e="T40">a n'est pas faux. </ts><ts n="e" id="Seg_1586" s="T40" e="T41">((aspire))</ts></ts><ts n="sc" id="Seg_1587" s="T44" e="T45"><ts n="e" id="Seg_1589" s="T44" e="T45">Ce n'est pas vrai. </ts></ts