3040" s="T60" e="T61">C</ts><ts n="e" id="Seg_3042" s="T61" e="T62">e n'est pas exact. </ts></ts><ts n="sc" id="Seg_3043" s="T63" e="T69"><ts n="e" id="Seg_3045" s="T63" e="T64">Ce n'est pas… </ts><ts n="e" id="Seg_3047" s="T64" e="T65">(Bon enfin) je n'ai jamais </ts><ts n="e" id="Seg_3049" s="T65" e="T66">été Mi</ts><ts n="e" id="Seg_3051" s="T66" e="T67">nistre de l'Éducation </ts><ts n="e" id="Seg_3053" s="T67" e="T68">Nationale, </ts><ts n="e" id="Seg_3055" s="T68" e="T69">Madame. </ts></ts><ts n="sc" id="Seg_3056" s="T71" e="T74"><ts n="e" id="Seg_3058" s="T71" e="T72">Bon </ts><ts n="e" id="Seg_3060" s="T72" e="T73">• • </ts><ts n="e" id="Seg_3062" s="T73" e="T74">((inc.)), excusez-moi. </ts></ts><ts n="sc" id="Seg_3063" s="T75" e="T85"><ts n="e" id="Seg_3065" s="T75" e="T76">Je/ </ts><ts n="e" id="Seg_3067" s="T76" e="T77">• • • </ts><ts n="e" id="Seg_3069" s="T77" e="T78">j'ai ja</ts><ts n="e" id="Seg_3071" s="T78" e="T79">mais été </ts><ts n="e" id="Seg_3073" s="T79" e="T80">Premier mi</ts><ts n="e" id="Seg_3075" s="T80" e="T81">nistre non plus. </ts><ts n="e" id="Seg_3077" s="T81" e="T82">• • </ts><ts n="e" id="Seg_3079" s="T82" e="T83">Mais/ mais/ </ts><ts n="e" id="Seg_3081" s="T83" e="T84">• • </ts><ts n="e" id="Seg_3083" s="T84" e="T85">mais… </ts></ts><ts n="sc" id="Seg_3084" s="T86" e="T89"><ts n="e" id="Seg_3086" s="T86" e="T87">Mais je </ts><ts n="e" id="Seg_3088" s="T87" e="T88">ne le suis pas </ts><ts n="e" id="Seg_3090" s="T88" e="T89">du tout, Madame. </ts></ts><ts n="sc" id="Seg_3091" s="T90" e="T91"><ts n="e" id="Seg_3093" s="T90" e="T91">Je le suis pas du tout. </ts></ts><ts n="sc" id="Seg_3094" s="T93" e="T94"><ts n="e" id="Seg_3096" s="T93" e="T94">(E)˙ </ts></ts><ts n="sc" id="Seg_3097" s="T100" e="T104"><ts n="e" id="Seg_3099" s="T100" e="T101">Mais en </ts><ts n="e" id="Seg_3101" s="T101" e="T102">quoi est elle saine, </ts><ts n="e" id="Seg_3103" s="T102" e="T103">votre </ts><ts n="e" id="Seg_3105" s="T103" e="T104">colère? </ts></ts><ts n="sc" id="Seg_3106" s="T105" e="T135"><ts n="e" id="Seg_3108" s="T105" e="T106">• </ts><ts n="e" id="Seg_3110" s="T106" e="T107">Traiter </ts><ts n="e" id="Seg_3112" s="T107" e="T108">votre contra</ts><ts n="e" id="Seg_3114" s="T108" e="T109">dicteur d'immo</ts><ts n="e" id="Seg_3116" s="T109" e="T110">rale </ts><ts n="e" id="Seg_3118" s="T110" e="T111">• • </ts><ts n="e" id="Seg_3120" s="T111" e="T112">et de menteu</ts><ts n="e" id="Seg_3122" s="T112" e="T113">r, </ts><ts n="e" id="Seg_3124" s="T113" e="T114">je vois pas ce que ça a de sain </ts><ts n="e" id="Seg_3126" s="T114" e="T115">• • </ts><ts n="e" id="Seg_3128" s="T115" e="T116">et d'utile. </ts><ts n="e" id="Seg_3130" s="T116" e="T117">• • </ts><ts n="e" id="Seg_3132" s="T117" e="T118">Vous avez la vision sectaire/ </ts><ts n="e" id="Seg_3134" s="T118" e="T119">vous </ts><ts n="e" id="Seg_3136" s="T119" e="T120">avez la sec/ </ts><ts n="e" id="Seg_3138" s="T120" e="T121">• • </ts><ts n="e" id="Seg_3140" s="T121" e="T122">• </ts><ts n="e" id="Seg_3142" s="T122" e="T123">la vi</ts><ts n="e" id="Seg_3144" s="T123" e="T124">sion </ts><ts n="e" id="Seg_3146" s="T124" e="T125">sectaire de la gauche. </ts><ts n="e" id="Seg_3148" s="T125" e="T126">• • </ts><ts n="e" id="Seg_3150" s="T126" e="T127">• • </ts><ts n="e" id="Seg_3152" s="T127" e="T128">Toute personne </ts><ts n="e" id="Seg_3154" s="T128" e="T129">qui ne pense pas exactement comme vous </ts><ts n="e" id="Seg_3156" s="T129" e="T130">((aspire)) </ts><ts n="e" id="Seg_3158" s="T130" e="T131">est forcément un </ts><ts n="e" id="Seg_3160" s="T131" e="T132">illégitime. </ts><ts n="e" id="Seg_3162" s="T132" e="T133">• • </ts><ts n="e" id="Seg_3164" s="T133" e="T134">(A bon) </ts><ts n="e" id="Seg_3166" s="T134" e="T135">c'est comme ça! </ts></ts><ts n="sc" id="Seg_3167" s="T140" e="T143"><ts n="e" id="Seg_3169" s="T140" e="T141">Ça me paraît </ts><ts n="e" id="Seg_3171" s="T141" e="T142">impor</ts><ts n="e" id="Seg_3173" s="T142" e="T143">tant. </ts></ts><ts n="sc" id="Seg_3174" s="T147" e="T148"><ts n="e" id="Seg_3176" s="T147" e="T148">(Oui bien sûr) </ts></ts><ts n="sc" id="Seg_3177" s="T165" e="T166"><ts n="e" id="Seg_3179" s="T165" e="T166">C'est vrai. </ts></ts><ts n="sc" id="Seg_3180" s="T169" e="T170"><ts n="e" id="Seg_3182" s="T169" e="T170">((inc.)) (bien sûr). </ts></ts><ts n="sc" id="Seg_3183" s="T173" e="T177"><ts n="e" id="Seg_3185" s="T173" e="T174">Et c'est une/ </ts><ts n="e" id="Seg_3187" s="T174" e="T175">• • </ts><ts n="e" id="Seg_3189" s="T175" e="T176">c'est une question de conception </ts><ts n="e" id="Seg_3191" s="T176" e="T177">de la politique. </ts></ts><ts n="sc" id="Seg_3192" s="T178" e="T182"><ts n="e" id="Seg_3194" s="T178" e="T179">Il faut </ts><ts n="e" id="Seg_3196" s="T179" e="T180">savoir garder son cal</ts><ts n="e" id="Seg_3198" s="T180" e="T181">me et ses </ts><ts n="e" id="Seg_3200" s="T181" e="T182">nerfs. </ts></ts><ts n="sc" id="Seg_3201" s="T185" e="T199"><ts n="e" id="Seg_3203" s="T185" e="T186">Et utiliser des </ts><ts n="e" id="Seg_3205" s="T186" e="T187">mots </ts><ts n="e" id="Seg_3207" s="T187" e="T188">• • </ts><ts n="e" id="Seg_3209" s="T188" e="T189">qui ne sont pas des mots qui bl</ts><ts n="e" id="Seg_3211" s="T189" e="T190">essent. </ts><ts n="e" id="Seg_3213" s="T190" e="T191">• • </ts><ts n="e" id="Seg_3215" s="T191" e="T192">Parce que quand on </ts><ts n="e" id="Seg_3217" s="T192" e="T193">emploie des mots/ </ts><ts n="e" id="Seg_3219" s="T193" e="T194">• • • </ts><ts n="e" id="Seg_3221" s="T194" e="T195">quand on emploie des mots qui blessent, </ts><ts n="e" id="Seg_3223" s="T195" e="T196">on divise son peuple, </ts><ts n="e" id="Seg_3225" s="T196" e="T197">• • • </ts><ts n="e" id="Seg_3227" s="T197" e="T198">alors qu'il faut le rassem</ts><ts n="e" id="Seg_3229" s="T198" e="T199">bler. </ts></ts><ts n="sc" id="Seg_3230" s="T201" e="T204"><ts n="e" id="Seg_3232" s="T201" e="T202">Non pour moi… </ts><ts n="e" id="Seg_3234" s="T202" e="T203">• • </ts><ts n="e" id="Seg_3236" s="T203" e="T204">Puis vous savez moi je… </ts></ts><ts n="sc" id="Seg_3237" s="T205" e="T213"><ts n="e" id="Seg_3239" s="T205" e="T206">Ben non. </ts><ts n="e" id="Seg_3241" s="T206" e="T207">• • </ts><ts n="e" id="Seg_3243" s="T207" e="T208">Puis je/ je </ts><ts n="e" id="Seg_3245" s="T208" e="T209">veux même vous dire </ts><ts n="e" id="Seg_3247" s="T209" e="T210">quelque </ts><ts n="e" id="Seg_3249" s="T210" e="T211">chose, je vous/ </ts><ts n="e" id="Seg_3251" s="T211" e="T212">je vous en veux pas, </ts><ts n="e" id="Seg_3253" s="T212" e="T213">parce ce que ça peut arriver à tout le monde de s'énerver. </ts></ts><ts n="sc" id="Seg_3254" s="T219" e="T220"><ts n="e" id="Seg_3256" s="T219" e="T220">Sur l'Europe </ts></ts></segmentation><annotation name="en" tierref="TIE3"><ta id="Seg_3257" s="T36" e="T38">That's wrong Madame. </ta><ta id="Seg_3258" s="T39" e="T47">These days there are three times more handicapped children at school than in your time, Madame. </ta><ta id="Seg_3259" s="T48" e="T51">That's wrong, Madame. </ta><ta id="Seg_3260" s="T52" e="T53">You have not... </ta><ta id="Seg_3261" s="T54" e="T56">No, Madame. </ta><ta id="Seg_3262" s="T58" e="T59">But... </ta><ta id="Seg_3263" s="T60" e="T62">That is not correct. </ta><ta id="Seg_3264" s="T63" e="T64">That is not... </ta><ta id="Seg_3265" s="T64" e="T69">(Well after all) I never was minister of education, Madame. </ta><ta id="Seg_3266" s="T71" e="T74">Well • • ((inc.)) excuse me. </ta><ta id="Seg_3267" s="T75" e="T81">I/ • • • I've never been Prime Minister either. </ta><ta id="Seg_3268" s="T81" e="T82">• • </ta><ta id="Seg_3269" s="T82" e="T83">But/ but/ </ta><ta id="Seg_3270" s="T83" e="T84">• • </ta><ta id="Seg_3271" s="T84" e="T85">but... </ta><ta id="Seg_3272" s="T86" e="T89">But I am not at all, Madame. </ta><ta id="Seg_3273" s="T90" e="T91">I am not at all. </ta><ta id="Seg_3274" s="T100" e="T102">But in how far is it sane, </ta><ta id="Seg_3275" s="T102" e="T104">your anger? </ta><ta id="Seg_3276" s="T105" e="T106">• </ta><ta id="Seg_3277" s="T106" e="T110">Treating your opponent as an immoral </ta><ta id="Seg_3278" s="T110" e="T111">• • </ta><ta id="Seg_3279" s="T111" e="T113">and as a liar, </ta><ta id="Seg_3280" s="T113" e="T114">I don't see how this can be sane </ta><ta id="Seg_3281" s="T114" e="T115">• • </ta><ta id="Seg_3282" s="T115" e="T116">and useful. </ta><ta id="Seg_3283" s="T116" e="T117">• • </ta><ta id="Seg_3284" s="T117" e="T118">You have the sectarian attitude </ta><ta id="Seg_3285" s="T118" e="T120">you have the sec/ </ta><ta id="Seg_3286" s="T120" e="T121">• • </ta><ta id="Seg_3287" s="T121" e="T122">• </ta><ta id="Seg_3288" s="T122" e="T125">the sectarian attitude of the Left. </ta><ta id="Seg_3289" s="T125" e="T126">• • </ta><ta id="Seg_3290" s="T126" e="T127">• • </ta><ta id="Seg_3291" s="T127" e="T128">Anybody </ta><ta id="Seg_3292" s="T128" e="T129">who does think exactly like you </ta><ta id="Seg_3293" s="T129" e="T130">((breathes)) </ta><ta id="Seg_3294" s="T130" e="T132">is inevitably illegitimate. </ta><ta id="Seg_3295" s="T132" e="T133">• • </ta><ta id="Seg_3296" s="T133" e="T135">Well that's how it is! </ta><ta id="Seg_3297" s="T140" e="T143">That seems important to me. </ta><ta id="Seg_3298" s="T147" e="T148">(Yes of course) </ta><ta id="Seg_3299" s="T165" e="T166">That's right. </ta><ta id="Seg_3300" s="T169" e="T170">((inc.)) (of course). </ta><ta id="Seg_3301" s="T173" e="T174">And that is a/ </ta><ta id="Seg_3302" s="T174" e="T175">• • </ta><ta id="Seg_3303" s="T175" e="T176">that is a question of the conception </ta><ta id="Seg_3304" s="T176" e="T177">of politics. </ta><ta id="Seg_3305" s="T178" e="T182">You have to stay calm and not lose your nerves. </ta><ta id="Seg_3306" s="T185" e="T187">And use words </ta><ta id="Seg_3307" s="T187" e="T188">• • </ta><ta id="Seg_3308" s="T188" e="T190">that are words that do not offend. </ta><ta id="Seg_3309" s="T191" e="T193">Because if you use word/ </ta><ta id="Seg_3310" s="T193" e="T194">• • • </ta><ta id="Seg_3311" s="T194" e="T195">when you use words that offend </ta><ta id="Seg_3312" s="T195" e="T196">you divide your people </ta><ta id="Seg_3313" s="T196" e="T197">• • • </ta><ta id="Seg_3314" s="T197" e="T199">when you should unite them. </ta><ta id="Seg_3315" s="T201" e="T202">No for me… </ta><ta id="Seg_3316" s="T202" e="T203">• • </ta><ta id="Seg_3317" s="T203" e="T204">You know me I… </ta><ta id="Seg_3318" s="T205" e="T206">Well no. </ta><ta id="Seg_3319" s="T206" e="T207">• • </ta><ta id="Seg_3320" s="T207" e="T208">Can I/ I </ta><ta id="Seg_3321" s="T208" e="T211">event want to tell you something I am/  </ta><ta id="Seg_3322" s="T211" e="T212">I am not angry with you </ta><ta id="Seg_3323" s="T212" e="T213">because it can happen to anybody, losing their nerve. </ta><ta id="Seg_3324" s="T219" e="T220">Of Europe. </ta></annotation></segmented-tier><segmented-tier id="TIE4" speaker="SPK2" category="v" type="t" display-name="PP [v]"><timeline-fork start="T1" end="T2"><tli id="T1.TIE4.1"/>
